const advanceDelivery=async(row:any)=>{if(!supabase)return;const next:Record<string,string>={assigned:'collecting',collecting:'at_hub',at_hub:'out_for_delivery',out_for_delivery:'delivered'};const status=next[row.shipment_status];if(!status)return;try{const {error}=await supabase.rpc('courier_update_shipment',{p_shipment_id:row.shipment_id,p_new_status:status,p_proof_url:null,p_delivery_otp:status==='delivered'?courierOtp:null});if(error)throw error;setCourierOtp('');notify('تم تحديث حالة التوصيل');await loadDashboard()}catch(error){notify(error instanceof Error?error.message:'تعذر تحديث التوصيل')}}
const [notificationsBusy,setNotificationsBusy]=useState(false)
