const markAllNotificationsRead=async()=>{if(!supabase||!authUser)return;const uid=(authUser as any).id;const readAt=new Date().toISOString();const {error}=await supabase.from('notifications').update({read_at:readAt}).eq('user_id',uid).is('read_at',null);if(error){notify(error.message);return}setNotificationRows(rows=>rows.map(row=>({...row,read_at:row.read_at||readAt})));notify('تم وضع جميع الإشعارات كمقروءة')}
useEffect(()=>{if(!supabase||!authUser){setNotificationRows([]);return}let alive=true;const uid=(authUser as any).id;const load=async()=>{const {data,error}=await supabase.from('notifications').select('id,title,body,kind,data,read_at,created_at').eq('user_id',uid).order('created_at',{ascending:false}).limit(50);if(alive&&!error)setNotificationRows(data||[])};void load();const channel=supabase.channel('toor-notifications-'+uid).on('postgres_changes',{event:'*',schema:'public',table:'notifications',filter:'user_id=eq.'+uid},()=>void load()).subscribe();return()=>{alive=false;void supabase.removeChannel(channel)}},[authUser])

const orderJourneyStages=[{key:'placed',title:'تم استلام الطلب',description:'تم تسجيل طلبك بنجاح في منصة TOOR BE.'},{key:'confirmed',title:'تأكيد الطلب',description:'تم تأكيد الطلب وإرساله إلى المتجر.'},{key:'preparing',title:'قيد التجهيز',description:'يقوم المتجر بتجهيز المنتجات وتغليفها.'},{key:'ready_for_pickup',title:'جاهز للاستلام',description:'اكتمل تجهيز المنتجات وأصبحت جاهزة للمندوب.'},{key:'assigned',title:'تم تعيين المندوب',description:'تم إسناد الشحنة إلى مندوب التوصيل.'},{key:'collecting',title:'استلام الشحنة من المتجر',description:'المندوب في مرحلة استلام الشحنة من المتجر.'},{key:'at_hub',title:'وصلت مركز التجميع',description:'تم تسجيل وصول الشحنة إلى مركز التجميع.'},{key:'out_for_delivery',title:'خرجت للتوصيل',description:'الشحنة في طريقها إلى عنوانك.'},{key:'delivered',title:'تم التسليم واستلام المبلغ',description:'تم التحقق من رمز الاستلام وتوثيق تسليم الطلب واستلام المبلغ النقدي.'}];
const getOrderJourneyIndex=(order:any)=>{if(order?.returns?.length)return 8;if(order?.status==='delivered')return 8;const shipment=order?.shipments?.[0]||order?.shipments||{};const shipmentStatus=shipment?.status;const itemStatuses=(order?.order_items||[]).map((item:any)=>item.merchant_status);if(shipmentStatus==='out_for_delivery')return 7;if(shipmentStatus==='at_hub')return 6;if(shipmentStatus==='collecting')return 5;if(shipmentStatus==='assigned')return 4;if(itemStatuses.length&&itemStatuses.every((x:string)=>x==='ready_for_pickup'))return 3;if(itemStatuses.some((x:string)=>x==='preparing'||x==='accepted'))return 2;if(order?.status==='confirmed')return 1;return 0};
const getOrderBucket=(order:any)=>{if(order?.returns?.length)return 'returns';if(order?.status==='delivered')return 'delivered';if((order?.shipments||[]).some((x:any)=>['assigned','collecting','at_hub','out_for_delivery'].includes(x.status)))return 'shipped';return 'preparing'};
const matchesOrderBucket=(order:any,bucket:string)=>{if(bucket==='all')return true;if(bucket==='unpaid')return order?.status!=='delivered'&&!order?.returns?.length;if(bucket==='delivered')return order?.status==='delivered';return getOrderBucket(order)===bucket};
const getMerchantJourneyIndex=(line:any)=>{const ship=line?.orders?.shipments?.[0];if(line?.orders?.status==='delivered')return 8;if(ship?.status==='out_for_delivery')return 7;if(ship?.status==='at_hub')return 6;if(ship?.status==='collecting')return 5;if(ship?.status==='assigned')return 4;if(line?.merchant_status==='ready_for_pickup')return 3;if(line?.merchant_status==='preparing')return 2;if(line?.merchant_status==='accepted')return 1;return 0};
const loadMyOrders=async()=>{if(!supabase||!authUser){setPage('account');setDrawer('account');return}setOrdersBusy(true);try{const {data,error}=await supabase.from('orders').select('id,order_number,status,total_jod,created_at,delivered_at,order_events(event_type,description,created_at),shipments(status),returns(id,status,reason,requested_at)').order('created_at',{ascending:false}).limit(30);if(error)throw error;setMyOrders(data||[]);setPage('account')}catch(error){notify(error instanceof Error?error.message:'تعذر تحميل الطلبات')}finally{setOrdersBusy(false)}}
const revealDeliveryCode=async(orderId:string)=>{if(!supabase||!authUser){notify('سجّل الدخول لعرض رمز التسليم');return}setDeliveryCodeBusy(orderId);try{const {data,error}=await supabase.rpc('regenerate_delivery_otp',{p_order_id:orderId});if(error)throw error;const code=typeof data==='string'?data:Array.isArray(data)?String(data[0]??''):'';if(!/^\d{6}$/.test(code))throw new Error('تعذر استلام رمز التسليم من الخادم');setOrderDeliveryCodes(current=>({...current,[orderId]:code}));notify('تم إصدار رمز التسليم. أعطه للمندوب عند وصوله فقط.')}catch(error){notify(error instanceof Error?error.message:'تعذر إصدار رمز التسليم')}finally{setDeliveryCodeBusy(null)}}
const submitReturnRequest=async(orderId:string)=>{if(!supabase||!authUser){notify('سجّل الدخول أولاً');return}const order=myOrders.find((item:any)=>item.id===orderId);if(!order||order.status!=='delivered'){notify('يمكن طلب الإرجاع بعد تسليم الطلب فقط');return}if(order.returns?.length){notify('يوجد طلب إرجاع مسجل لهذا الطلب');return}if(!returnReason.trim()){notify('اختر سبب الإرجاع');return}setReturnBusy(true);try{const {data:userResult,error:userError}=await supabase.auth.getUser();if(userError||!userResult.user)throw userError||new Error('يرجى تسجيل الدخول مجدداً');const {error}=await supabase.from('returns').insert({order_id:orderId,buyer_id:userResult.user.id,reason:returnReason,details:returnDetails.trim()||null});if(error)throw error;setReturnOrderId(null);setReturnDetails('');notify('تم إرسال طلب الإرجاع للإدارة للمراجعة');await loadMyOrders()}catch(error){notify(error instanceof Error?error.message:'تعذر إرسال طلب الإرجاع')}finally{setReturnBusy(false)}}

const submitSellerApplication=async()=>{if(!supabase||!authUser){notify('سجّل الدخول أولاً لتقديم طلب التاجر');setDrawer('account');return}if(!storeName.trim()||!storePhone.trim()||!storeCity.trim()){notify('أكمل اسم المتجر والهاتف والمدينة');return}setSellerBusy(true);try{const {data:userResult,error:userError}=await supabase.auth.getUser();if(userError||!userResult.user)throw userError||new Error('يرجى تسجيل الدخول مجدداً');const {error}=await supabase.from('merchant_applications').insert({user_id:userResult.user.id,proposed_store_name:storeName.trim(),contact_phone:storePhone.trim(),city:storeCity.trim(),business_description:storeDescription.trim()});if(error)throw error;notify('تم إرسال طلب الانضمام للإدارة للمراجعة');setDrawer(null);setStoreName('');setStorePhone('');setStoreDescription('')}catch(error){notify(error instanceof Error?error.message:'تعذر إرسال الطلب')}finally{setSellerBusy(false)}}
useEffect(()=>{if(!supabase||drawer!=='dashboard'||!['admin','merchant','courier'].includes(profileRole))return;const channel=supabase.channel('toor-dashboard-live-'+profileRole).on('postgres_changes',{event:'*',schema:'public',table:'shipments'},()=>void loadDashboard()).on('postgres_changes',{event:'*',schema:'public',table:'order_items'},()=>void loadDashboard()).on('postgres_changes',{event:'*',schema:'public',table:'support_reports'},()=>{if(profileRole==='admin')void loadDashboard()}).subscribe();return()=>{void supabase.removeChannel(channel)}},[drawer,profileRole])
const selectSavedAddress=(id:string)=>{setSelectedSavedAddressId(id);const a=savedAddresses.find((row:any)=>row.id===id);if(!a){setAddressName('');setAddressPhone('');setAddressCity('عمّان');setAddressArea('');setAddressStreet('');setAddressNotes('');setAddressLatitude(null);setAddressLongitude(null);return}setAddressName(a.recipient_name||'');setAddressPhone(a.phone||'');setAddressCity(a.city||'عمّان');setAddressArea(a.area||'');setAddressStreet(a.street||'');setAddressNotes(a.notes||'');setAddressLatitude(a.latitude??null);setAddressLongitude(a.longitude??null)}
const chooseCurrentLocation=(target:'buyer'|'merchant')=>{if(!navigator.geolocation){notify('خدمة تحديد الموقع غير مدعومة في هذا الهاتف');return}setLocationBusy(true);navigator.geolocation.getCurrentPosition(position=>{const lat=position.coords.latitude,lon=position.coords.longitude;if(target==='buyer'){setSelectedSavedAddressId('');setAddressLatitude(lat);setAddressLongitude(lon)}else{setStoreLatitude(lat);setStoreLongitude(lon)}setLocationBusy(false);notify('تم تحديد الموقع في النموذج')},()=>{setLocationBusy(false);notify('تعذر تحديد الموقع؛ اسمح للتطبيق باستخدام الموقع من إعدادات الهاتف')},{enableHighAccuracy:true,timeout:15000,maximumAge:60000})}
const openGoogleMaps=(target:'buyer'|'merchant')=>{const lat=target==='buyer'?addressLatitude:storeLatitude,lon=target==='buyer'?addressLongitude:storeLongitude;const url=lat!==null&&lon!==null?'https://www.google.com/maps/search/?api=1&query='+lat+','+lon:'https://www.google.com/maps';window.open(url,'_blank','noopener,noreferrer')}
const applyGoogleMapsLocation=(target:'buyer'|'merchant')=>{const raw=mapLocationUrl.trim();if(!raw){notify('الصق رابط الموقع الذي نسخته من خرائط Google');return}const decoded=decodeURIComponent(raw);const patterns=[/[!@]3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/i,/@(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)/,/(?:query|q)=(-?\d+(?:\.\d+)?)(?:%2C|,|%20|\s)+(-?\d+(?:\.\d+)?)/i,/(-?\d{1,3}\.\d{3,}),\s*(-?\d{1,3}\.\d{3,})/];let match:RegExpExecArray|null=null;for(const pattern of patterns){match=pattern.exec(decoded);if(match)break}if(!match){notify('لم أجد إحداثيات في الرابط. افتح الموقع المحدد في خرائط Google ثم اختر مشاركة ونسخ الرابط الكامل');return}const lat=Number(match[1]),lon=Number(match[2]);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){notify('إحداثيات الموقع غير صحيحة');return}if(target==='buyer'){setSelectedSavedAddressId('');setAddressLatitude(lat);setAddressLongitude(lon)}else{setStoreLatitude(lat);setStoreLongitude(lon)}setMapLocationUrl('');notify('تم استيراد موقع خرائط Google. احفظ العنوان أو موقع المتجر لإتمام الحفظ')}
const submitProductReview=async(product:Product)=>{if(!supabase||!authUser){notify('سجّل الدخول لتقييم المنتج');return}if(!product.dbId){notify('لا يمكن تقييم منتج تجريبي');return}setReviewBusy(true);try{const uid=(authUser as any).id;const {data:items,error:itemError}=await supabase.from('order_items').select('id,orders!inner(buyer_id,status)').eq('product_id',product.dbId).eq('orders.buyer_id',uid).eq('orders.status','delivered').limit(30);if(itemError)throw itemError;if(!items?.length)throw new Error('يمكنك تقييم المنتج بعد استلامه فقط');const {data:reviews,error:reviewLookupError}=await supabase.from('product_reviews').select('order_item_id').in('order_item_id',items.map((row:any)=>row.id));if(reviewLookupError)throw reviewLookupError;const reviewed=new Set((reviews||[]).map((row:any)=>row.order_item_id));const item=items.find((row:any)=>!reviewed.has(row.id));if(!item)throw new Error('لقد قيّمت جميع مشترياتك السابقة من هذا المنتج');const {error}=await supabase.from('product_reviews').insert({product_id:product.dbId,user_id:uid,order_item_id:item.id,rating:reviewRating,review_text:reviewText.trim()});if(error)throw error;setCatalog(rows=>rows.map(row=>row.id===product.id?{...row,rating:((row.rating*row.reviews)+reviewRating)/(row.reviews+1),reviews:row.reviews+1,reviewEntries:[{name:profileFullName||'أنت',rating:reviewRating,text:reviewText.trim(),createdAt:new Date().toISOString()},...(row.reviewEntries||[])]}:row));setSelected(current=>current&&current.id===product.id?{...current,rating:((current.rating*current.reviews)+reviewRating)/(current.reviews+1),reviews:current.reviews+1,reviewEntries:[{name:profileFullName||'أنت',rating:reviewRating,text:reviewText.trim(),createdAt:new Date().toISOString()},...(current.reviewEntries||[])]}:current);setReviewText('');setReviewModalOpen(false);notify('شكراً لك، تم إرسال تقييمك وسيظهر بعد اعتماده');}catch(error){notify(error instanceof Error?error.message:'تعذر إرسال التقييم')}finally{setReviewBusy(false)}}
const applyCoupon=async()=>{if(!supabase||!authUser){notify('سجّل الدخول لاستخدام الكوبون');setPage('account');return}if(!couponCode.trim()){notify('أدخل رمز الكوبون');return}const items=selectedCartEntries.map(([,line])=>({product_id:catalog.find(p=>p.id===line.productId)?.dbId,quantity:line.quantity})).filter(x=>x.product_id);if(!items.length||items.length!==selectedCartEntries.length){notify('الكوبونات متاحة على المنتجات الفعلية من المتاجر');return}setCouponBusy(true);try{const {data,error}=await supabase.rpc('preview_coupon',{p_code:couponCode.trim(),p_items:items});if(error)throw error;setAppliedCoupon(couponCode.trim().toUpperCase());setCouponDiscount(Number(data||0));notify('تم التحقق من القسيمة وتطبيقها على طلبك')}catch(error){setAppliedCoupon('');setCouponDiscount(0);notify(error instanceof Error?error.message:'تعذر تطبيق الكوبون')}finally{setCouponBusy(false)}}
